fn bitwise_xor(a: Vec<u8>, b: Vec<u8>) -> Vec<u8> {
    // Precondition: a.len() == b.len(), a.len() > 0
    // Postcondition: output length equals input length, 
    // and output[i] == a[i] ^ b[i] for all i

    // Initialize a vector to hold the result with the same length as inputs
    let mut res = Vec::with_capacity(a.len());

    // Iterate over the indices, compute XOR elementwise
    for i in 0..a.len() {
        res.push(a[i] ^ b[i]);
    }

    res
}